def guess_string(n, prefixes_suffixes):
    # Create a list to store the result
    result = [''] * (2 * n - 2)

    # Create a dictionary to store the count of each prefix and suffix
    prefix_count = {}
    suffix_count = {}

    # Count the occurrences of each prefix and suffix
    for i, prefix_suffix in enumerate(prefixes_suffixes):
        if prefix_suffix not in prefix_count:
            prefix_count[prefix_suffix] = 0
        if i < n - 1:
            prefix_count[prefix_suffix] += 1
        else:
            suffix_count[prefix_suffix] = 0
        if i >= n - 1:
            suffix_count[prefix_suffix] += 1

    # Try to determine the correct order of prefixes and suffixes
    possible_order = []
    for prefix_suffix in prefix_count:
        if prefix_count[prefix_suffix] == 1 and suffix_count.get(prefix_suffix, 0) == 1:
            possible_order.append(prefix_suffix)

    # Sort possible_order by length
    possible_order.sort(key=len)

    # Try to build the string by alternating between prefixes and suffixes
